import { labMetrics as m } from "@/data/lab-metrics";

// The Lab page's words. Every number about the shipped model comes from lab-metrics.ts
// (generated by ml/export_lab.py); the few hand-written numbers below are from earlier
// runs and are documented in ml/README.md.

const pct = (x: number) => `${(x * 100).toFixed(1)}%`;

/** The headline tiles: what a recruiter should remember. */
export const labHeadline = [
  { value: `${(m.model.parameters / 1e6).toFixed(1)}M`, label: "parameters, trained from random weights" },
  { value: pct(m.test.exactMatch), label: `exact answers on ${m.test.questions} questions it never saw` },
  { value: `${m.test.fabricated} / ${m.test.answered}`, label: "answers that invented a fact" },
  { value: "$0", label: `to serve: ${m.model.downloadMB} MB, runs in your browser` },
];

/** How one question flows through the system, with the number that proves each step. */
export const labPipeline = [
  {
    step: "Guard",
    title: "Private topics stop here",
    description: "Age, address, phone or finances get a polite refusal before the model even runs.",
    stat: `${m.test.refusedSafely}/${m.test.shouldRefuse}`,
    statLabel: "unsafe questions handled",
  },
  {
    step: "Retrieve",
    title: "TF-IDF finds the facts",
    description: `Ranks ${m.data.chunks} chunks of my profile and keeps only the confident matches (τ = 0.10).`,
    stat: pct(m.test.recallAt3),
    statLabel: "right chunk in the top 3",
  },
  {
    step: "Generate",
    title: "The transformer answers",
    description: "Reads up to 3 chunks plus the question and writes the reply one token at a time.",
    stat: `${m.model.context}`,
    statLabel: "tokens of context",
  },
  {
    step: "Verify",
    title: "Guardrails check every claim",
    description: "Each name, date and number must appear in what it read; if not, a safe fallback is shown.",
    stat: `${m.test.fabricated}`,
    statLabel: "invented facts on the test set",
  },
];

/** Training runs compared on the same 453 rephrased questions (ml/README.md, Phase 4). */
export const labVersions = [
  { version: "v4", params: "3.9M", change: "Clean data, balanced phrasings", stress: 0.627, test: 0.681 },
  { version: "v5a", params: "11.7M", change: "3× bigger, 25× more pretraining", stress: 0.517 },
  { version: "v5b", params: "11.7M", change: "Same, higher learning rate", stress: 0.541 },
  { version: "v6", params: "3.9M", change: "v4 + a paraphrase grammar", stress: 0.755, test: m.test.exactMatch, final: true },
];

/** What six training runs taught me, one number each. */
export const labLessons = [
  {
    title: "Bigger was worse",
    body: "3× the parameters and 25× the pretraining scored up to 11 points lower on new phrasings. It memorized faster.",
  },
  {
    title: "Data beat size",
    body: `Generating fresh phrasings every epoch took the same ${(m.model.parameters / 1e6).toFixed(1)}M model from 68.1% to ${pct(m.test.exactMatch)} on the test set.`,
  },
  {
    title: "Dev sets wear out",
    body: `After five rounds of decisions, dev said 94% and test said 78%. A separate ${m.data.stress}-question stress set predicted test within 3 points.`,
  },
];

